params {
    // Optional parameters for Demuxem - Default values
    threads = 1
    genome = null
    alpha_on_samples = 0.0
    min_num_genes = 100
    min_num_umis = 100
    min_signal_hashtag = 10.0
    random_state = 0

}


process {

    withName: DEMUXEM {
        ext.args = "--threads ${params.threads} --alpha-on-samples ${params.alpha_on_samples} --min-num-genes ${params.min_num_genes}  --min-num-umis ${params.min_num_umis} --min-signal-hashtag ${params.min_signal_hashtag} --random-state ${params.random_state}"
    }

}

// nf-core modules test demuxem
nextflow_process {

    name "Test Process DEMUXEM"
    script "../main.nf"
    process "DEMUXEM"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "demuxem"

    test("Standard_Multiome - h5 - csv") {

        when {
            process {
                """

                input[0] = [
                    [ id:'sample1'],
                    file(params.modules_testdata_base_path + "/genomics/homo_sapiens/10xgenomics/cellranger/hashing_demultiplexing/438-21-raw_feature_bc_matrix.h5",checkIfExists: true),
                    file(params.modules_testdata_base_path + "/genomics/homo_sapiens/10xgenomics/cellranger/hashing_demultiplexing/438_21_raw_HTO.csv",checkIfExists: true)
                    ]
                input[1] = ""
                input[2] = ""
                input[3] = ""
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    file(process.out.zarr[0][1]).name,
                    file(process.out.out_zarr[0][1]).name,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }

    }

    test("Standard_Multiome - h5 - csv - stub") {

        options "-stub"

        when {
            process {
                """

                input[0] = [
                    [ id:'sample1'],
                    file(params.modules_testdata_base_path + "/genomics/homo_sapiens/10xgenomics/cellranger/hashing_demultiplexing/438-21-raw_feature_bc_matrix.h5",checkIfExists: true),
                    file(params.modules_testdata_base_path + "/genomics/homo_sapiens/10xgenomics/cellranger/hashing_demultiplexing/438_21_raw_HTO.csv",checkIfExists: true)
                    ]
                input[1] = ""
                input[2] = ""
                input[3] = "True"
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

}

